async def connect_gateway(base_url: str, *, token: str) -> GatewayRpcClient:
    scheme, separator, address = base_url.rstrip("/").partition("://")
    gateway_url = f"{scheme.replace('http', 'ws', 1)}{separator}{address}"
    connection = GatewayRpcClient.connect(
        gateway_url=gateway_url,
        headers={"Authorization": f"Bearer {token}"},
        lazy=True,
    )
    return await connection


